//! Second virial coefficient matrix comparisons against the exact-source
//! library.
//! Generated by tools/rust_port/validate_virial_matrix.py.
//! Copyright thermotools and Contributors. Apache-2.0.

#![allow(clippy::excessive_precision)]

use thermopack_rs::Cubic;
use thermopack_rs::CubicKind;

const ATOL: f64 = 1.0e-8;
const RTOL: f64 = 1.0e-3;

#[test]
fn virial_matrices_match_the_source() {
    let mut checked = 0;
    for row in include_str!("fixtures/virial_matrix.csv").lines().skip(1) {
        let fields: Vec<_> = row.split(';').collect();
        let case = fields[0];
        let parts: Vec<_> = case.split('|').collect();
        let kind = match parts[0] {
            "SRK" => CubicKind::SoaveRedlichKwong,
            "RK" => CubicKind::RedlichKwong,
            "VDW" => CubicKind::VanDerWaals,
            _ => CubicKind::PengRobinson,
        };
        let components: Vec<&str> = parts[1].split(',').collect();
        let temperature: f64 = parts[2].parse().unwrap();
        let source: Vec<f64> = fields[1].split(',').map(|v| v.parse().unwrap()).collect();
        let model = Cubic::new(kind, &components).unwrap();
        let matrix = model.second_virial_coefficient_matrix(temperature).unwrap();
        assert_eq!(matrix.len(), source.len(), "{case}");
        for (position, (source, native)) in source.iter().zip(matrix.iter()).enumerate() {
            assert!(
                (source - native).abs() <= ATOL + RTOL * source.abs(),
                "{case} entry {position}: source {source} native {native}"
            );
        }
        checked += 1;
    }
    assert_eq!(checked, 6);
}

#[test]
fn the_matrix_is_symmetric() {
    // The cross coefficient of a pair is the same in both directions.
    let model = Cubic::new(CubicKind::PengRobinson, &["C1", "C3", "N2"]).unwrap();
    let matrix = model.second_virial_coefficient_matrix(300.0).unwrap();
    let count = model.components().len();
    for i in 0..count {
        for j in 0..count {
            assert!(
                (matrix[i * count + j] - matrix[j * count + i]).abs() < 1.0e-12,
                "{i} {j}"
            );
        }
    }
}
